#### Шаг 1: Установка SDL
Перед началом работы убедитесь, что у вас установлена библиотека SDL. Вы можете скачать и установить SDL с официального сайта: https://www.libsdl.org/

#### Шаг 2: Настройка проекта
Создайте новый проект в вашей IDE или настройте среду для компиляции C-кода. Добавьте в проект пути к заголовочным файлам и библиотекам SDL.

#### Шаг 3: Подготовка ресурсов
Подготовьте изображения, которые будут использоваться в игре: изображение змейки, фрукта, препятствий и фона. Сохраните их в папке проекта.

#### Шаг 4: Инициализация SDL и создание окна
```c
#include <SDL.h>

int main(int argc, char* argv[]) {
    SDL_Init(SDL_INIT_VIDEO); // Инициализация SDL
    SDL_Window* window = SDL_CreateWindow("Змейка", SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED, 800, 600, 0);
    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);

    // Загрузка текстур
    SDL_Surface* snakeSurface = SDL_LoadBMP("snake.bmp");
    SDL_Texture* snakeTexture = SDL_CreateTextureFromSurface(renderer, snakeSurface);
    SDL_FreeSurface(snakeSurface);

    // Основной цикл игры
    bool running = true;
    while (running) {
        SDL_Event event;
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                running = false;
            }
        }

        // Отрисовка
        SDL_RenderClear(renderer);
        SDL_RenderCopy(renderer, snakeTexture, NULL, NULL);
        SDL_RenderPresent(renderer);
    }

    // Освобождение ресурсов и выход
    SDL_DestroyTexture(snakeTexture);
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();
    return 0;
}
```

