5. Создайте новый файл с именем `snake.c` и добавьте в него следующий код:

```c
#include <stdio.h>
#include <stdlib.h>
#include <SDL2/SDL.h>
#include <SDL2/SDL_image.h>

#define WINDOW_WIDTH 800
#define WINDOW_HEIGHT 600
#define GRID_SIZE 20

// Структура для хранения позиций змейки
typedef struct Snake {
    int x[100], y[100]; // Максимум 100 клеток в змейке
    int length;
} Snake;

// Функция инициализации SDL и создания окна
int initSDL(SDL_Window **window, SDL_Renderer **renderer) {
    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        printf("SDL initialization failed: %s\n", SDL_GetError());
        return 1;
    }

    *window = SDL_CreateWindow(
        "Snake Game",
        SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
        WINDOW_WIDTH, WINDOW_HEIGHT,
        SDL_WINDOW_SHOWN
    );

    if (*window == NULL) {
        printf("Window creation failed: %s\n", SDL_GetError());
        SDL_Quit();
        return 1;
    }

    *renderer = SDL_CreateRenderer(*window, -1, SDL_RENDERER_ACCELERATED);
    if (*renderer == NULL) {
        printf("Renderer creation failed: %s\n", SDL_GetError());
        SDL_DestroyWindow(*window);
        SDL_Quit();
        return 1;
    }

    return 0;
}

// Функция инициализации изображений
SDL_Texture *loadTexture(SDL_Renderer *renderer, const char *filePath) {
    SDL_Texture *texture = NULL;
    SDL_Surface *loadedSurface = IMG_Load(filePath);
    if (loadedSurface == NULL) {
        printf("Unable to load image %s: %s\n", filePath, IMG_GetError());
    } else {
        texture = SDL_CreateTextureFromSurface(renderer, loadedSurface);
        SDL_FreeSurface(loadedSurface);
    }
    return texture;
}

// Функция очистки экрана
void clearScreen(SDL_Renderer *renderer, SDL_Texture *background) {
    SDL_RenderCopy(renderer, background, NULL, NULL);
    SDL_SetRenderDrawColor(renderer, 0, 0, 0, SDL_ALPHA_OPAQUE);
    SDL_RenderFillRect(renderer, NULL);
    SDL_RenderPresent(renderer);
}

// Функция рисования змейки на экране
void drawSnake(Snake *snake, SDL_Renderer *renderer) {
    int colorIndex = 0;
    for (int I = 0; I < snake->length; i++) {
        SDL_Rect snakeRect = {snake->x[i], snake->y[i], GRID_SIZE, GRID_SIZE};
        SDL_SetRenderDrawColor(renderer, (colorIndex % 6) * 64, (colorIndex % 12) * 32, 64 - ((colorIndex % 24) * 8), SDL_ALPHA_OPAQUE);
        SDL_RenderFillRect(renderer, &snakeRect);
        colorIndex++;
    }
}

// Функция проверки столкновений змейки с препятствиями
int isCollide(Snake *snake, SDL_Rect *rectangle) {
    for (int I = 0; I < snake->length; i++) {
        if (snake->x[i] >= rectangle->x && snake->x[i] < rectangle->x + rectangle->w &&
            snake->y[i] >= rectangle->y && snake->y[i] < rectangle->y + rectangle->h) {
            return 1;
        }
    }
    return 0;
}

// Функция обновления змейки
void updateSnake(Snake *snake, int direction) {
    int headX = snake->x[0];
    int headY = snake->y[0];

    switch (direction) {
        case SDL_SCANCODE_UP:
            headY -= GRID_SIZE;
            break;
        case SDL_SCANCODE_DOWN:
            headY += GRID_SIZE;
            break;
        case SDL_SCANCODE_LEFT:
            headX -= GRID_SIZE;
            break;
        case SDL_SCANCODE_RIGHT:
            headX += GRID_SIZE;
            break;
    }

    snake->x[0] = headX;
    snake->y[0] = headY;
}

// Функция обновления состояния игры
int updateGame(Snake *snake, SDL_Rect *apple, int *score, SDL_Renderer *renderer) {
    int direction = SDL_SCANCODE_RIGHT;

    // Обработка событий клавиатуры
    SDL_Event event;
    while (SDL_PollEvent(&event)) {
        if (event.type == SDL_KEYDOWN) {
            int key = event.key.keysym.sym;
            if (key == SDL_SCANCODE_UP || key == SDL_SCANCODE_DOWN || key == SDL_SCANCODE_LEFT || key == SDL_SCANCODE_RIGHT) {
                direction = key;
            }
        } else if (event.type == SDL_QUIT) {
            return 1; // Выход из игры
        }
    }

    // Обновление положения головы змейки
    updateSnake(snake, direction);

    // Проверка столкновения змейки с яблоком
    if (isCollide(snake, &apple->rect)) {
        int tailX = snake->x[snake->length - 1];
        int tailY = snake->y[snake->length - 1];
        snake->x[snake->length] = tailX;
        snake->y[snake->length] = tailY;
        snake->length++;

        // Увеличение счёта
        (*score)++;
    }

    // Проверка столкновения змейки с собой
    for (int I = 2; I < snake->length; i++) {
        if (snake->x[0] == snake->x[i] && snake->y[0] == snake->y[i]) {
            return 1; // Game Over
        }
    }

    // Очистка экрана
    clearScreen(renderer, snake->background);

    // Рисование змейки на экране
    drawSnake(snake, renderer);

    // Рисование яблока на экране
    SDL_Rect appleRect = apple->rect;
    SDL_SetRenderDrawColor(renderer, 255, 0, 0, SDL_ALPHA_OPAQUE);
    SDL_RenderFillRect(renderer, &appleRect);

    // Обновление экрана
    SDL_RenderPresent(renderer);
}

// Функция загрузки и инициализации уровня
int initLevel(Snake *snake, SDL_Rect *apple, SDL_Renderer *renderer) {
    // Загрузка изображений
    snake->background = loadTexture(renderer, "background.png");
    apple->texture = loadTexture(renderer, "apple.png");

    // Получение размеров текстур
    SDL_QueryTexture(snake->background, NULL, NULL, &snake->backgroundRect.w, &snake->backgroundRect.h);
    SDL_QueryTexture(apple->texture, NULL, NULL, &apple->rect.w, &apple->rect.h);

    // Установка начальных координат яблока
    apple->rect.x = (WINDOW_WIDTH - apple->rect.w) / 2;
    apple->rect.y = (WINDOW_HEIGHT - apple->rect.h) / 2;

    // Установка начальных координат головы змейки
    snake->x[0] = (WINDOW_WIDTH - GRID_SIZE) / 2;
    snake->y[0] = (WINDOW_HEIGHT - GRID_SIZE) / 2;

    // Установка начальных координат хвоста змейки
    snake->length = 1;
    snake->x[1] = snake->x[0] - GRID_SIZE;
    snake->y[1] = snake->y[0];

    return 0;
}

// Функция закрытия SDL и освобождения ресурсов
void closeSDL(SDL_Window *window, SDL_Renderer *renderer) {
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();
}

int main(int argc, char *argv[]) {
    SDL_Window *window;
    SDL_Renderer *renderer;

    if (initSDL(&window, &renderer)) {
        return 1;
    }

    Snake snake;
    SDL_Rect apple = {0};

    initLevel(&snake, &apple, renderer);

    int score = 0;

    while (1) {
        int result = updateGame(&snake, &apple, &score, renderer);

        if (result == 1) {
            break;
        }
    }

    closeSDL(window, renderer);

    return 0;
}
```

6. Создайте файлы `background.png` и `apple.png` в папке с проектом и добавьте в них изображения, соответствующие вашему дизайну.

7. Скомпилируйте и запустите проект.

